    >
      <v-progress-circular
        indeterminate
        color="primary"
        size="52"
      ></v-progress-circular>
      <div class="mt-4 grey--text text--darken-1">Verifying access…</div>
    </div>

    <!-- ── Access denied: not a Departmental Director ───────────────────── -->
