          </v-col>
          <v-col class="shrink">
            <v-icon size="48" color="error">mdi-lock-outline</v-icon>
          </v-col>
        </v-row>
      </v-alert>
    </v-container>

    <main v-else class="sl-body">
      <section class="sl-card">
        <!-- ── Card header ──────────────────────────────────────────── -->
        <div class="sl-card__head">
          <div class="sl-card__head-left">
            <div class="sl-card__chip">HOD</div>
            <h2 class="sl-card__title">HOD Recommended Transfers</h2>
          </div>
          <div class="sl-card__head-right">
            <span class="sl-card__sub" v-if="!loading">
