              {{ recommendations.length }} records
            </span>
            <v-btn
              color="primary"
              small
              depressed
              class="ml-4"
              @click="newRecommendation"
            >
              <v-icon small left>mdi-plus</v-icon>
              New Recommendation
            </v-btn>
          </div>
        </div>

        <!-- ── Loading ──────────────────────────────────────────────── -->
        <div v-if="loading" class="sl-loading">
          <v-progress-circular
            indeterminate
            color="primary"
            size="48"
          ></v-progress-circular>
          <span>Loading transfer recommendations…</span>
        </div>

        <template v-else>
          <!-- ── Filters ─────────────────────────────────────────────── -->
          <v-card-text class="pb-1 pt-3">
            <v-row dense>
              <v-col cols="12" sm="6" md="4">
                <v-text-field
                  v-model="filter.name"
                  label="Search staff name"
                  dense
                  outlined
                  hide-details
                  clearable
                  prepend-inner-icon="mdi-magnify"
                  class="ma-1"
                  @input="onFilterChange"
                  @click:clear="onFilterChange"
                />
              </v-col>

              <v-col cols="12" sm="6" md="3">
                <v-select
                  v-model="filter.status"
                  :items="statusOptions"
                  label="Status"
                  dense
                  outlined
                  hide-details
                  clearable
                  prepend-inner-icon="mdi-progress-check"
                  class="ma-1"
                  @change="onFilterChange"
                  @click:clear="onFilterChange"
                />
              </v-col>

              <v-col cols="12" sm="auto" class="d-flex align-center">
                <v-btn
                  v-if="hasActiveFilters"
                  text
                  small
                  color="red darken-1"
                  class="ma-1"
                  @click="resetFilters"
                >
                  <v-icon small left>mdi-close</v-icon>
                  Clear filters
                </v-btn>
              </v-col>
            </v-row>
          </v-card-text>

          <!-- ── Error banner ────────────────────────────────────────── -->
          <v-alert
            v-if="loadError"
            type="warning"
            dense
            outlined
            class="mx-4 mb-2"
          >
            {{ loadError }}
          </v-alert>

          <!-- ── Data table ──────────────────────────────────────────── -->
          <v-data-table
            :headers="tableHeaders"
            :items="filteredRecommendations"
            :items-per-page="15"
            :footer-props="{
              'items-per-page-options': [10, 15, 25, 50],
              'items-per-page-text': 'Rows per page',
            }"
            no-data-text="No transfer recommendations match the current filters"
            class="elevation-0"
            @click:row="viewRecommendation"
          >
            <template #[`item.staffName`]="{ item }">
              <div class="sl-table__primary">{{ item.staffName }}</div>
            </template>

            <template #[`item.current`]="{ item }">
              <div>{{ item.currentPosition }}</div>
              <span class="sl-table__muted">{{ item.currentFacility }}</span>
            </template>

            <template #[`item.destination`]="{ item }">
              <div>{{ item.destinationPosition }}</div>
              <span class="sl-table__muted">{{
                item.destinationFacility
              }}</span>
            </template>

            <template #[`item.plannedTransferDate`]="{ item }">
              <span class="sl-table__muted">{{
                formatDate(item.plannedTransferDate)
              }}</span>
            </template>

            <template #[`item.eventDate`]="{ item }">
              <span class="sl-table__muted">{{
                formatDate(item.eventDate)
              }}</span>
            </template>

            <template #[`item.status`]="{ item }">
              <span
                class="sl-status-pill"
                :class="'sl-status-pill--' + statusKey(item.status)"
              >
                <span class="sl-status-pill__dot"></span>
                {{ item.statusDisplay }}
              </span>
            </template>

            <template #[`item.actions`]="{ item }">
              <v-btn
                v-if="item.status === 'psapproved'"
                x-small
                depressed
                color="green darken-1"
                dark
                class="mr-1"
                @click.stop="applyTransfer(item)"
              >
                <v-icon x-small left>mdi-check-decagram</v-icon>Apply Transfer
              </v-btn>
              <v-btn icon small @click.stop="viewRecommendation(item)">
                <v-icon small>mdi-eye-outline</v-icon>
              </v-btn>
            </template>
          </v-data-table>
        </template>
      </section>
    </main>

    <v-snackbar
      v-model="snackbar.show"
      :color="snackbar.color"
      top
      right
      :timeout="4000"
    >
      {{ snackbar.text }}
      <template #action="{ attrs }">
        <v-btn text v-bind="attrs" @click="snackbar.show = false">Close</v-btn>
      </template>
    </v-snackbar>
  </div>
