<script>
import generalMixin from "../../mixins/general";

const PROFILE =
  "http://ihris.org/fhir/StructureDefinition/hod-recommended-transfer-profile";

export default {
  name: "HodTransferRecommendationList",
  mixins: [generalMixin],
  props: ["queries"],

  data() {
    return {
      accessChecked: false,
      isDirector: false,

      loading: true,
      loadError: null,
      recommendations: [],
      positionsMap: {},

      filter: { name: "", status: null },
      filterDebounce: null,
      filteredRecommendations: [],

      statusValueSetItems: [],

      tableHeaders: [
        { text: "Staff Name", value: "staffName", width: "180px" },
        { text: "Current Position", value: "current" },
        { text: "Destination Position", value: "destination" },
        {
          text: "Planned Transfer Date",
          value: "plannedTransferDate",
          sortable: false,
        },
        { text: "Submitted", value: "eventDate", sortable: false },
        { text: "Status", value: "status", sortable: false },
        { text: "", value: "actions", sortable: false, width: "160px" },
      ],

      snackbar: { show: false, text: "", color: "success" },
    };
  },

  computed: {
    statusOptions() {
      return this.statusValueSetItems.map((item) => ({
        text: item.display || item.code,
        value: item.code,
      }));
    },

    hasActiveFilters() {
      return !!this.filter.name || !!this.filter.status;
    },
  },

  async mounted() {
    await this.checkAccess();
    if (!this.isDirector) return;
    await Promise.all([this.loadStatusValueSet(), this.loadRecommendations()]);
  },

  methods: {
    async checkAccess() {
      try {
        // Wait for generalMixin to finish loading loggedInStaff
        await new Promise((resolve) => {
          if (!this.loadingUserData) {
            resolve();
            return;
          }
          const unwatch = this.$watch("loadingUserData", (newValue) => {
            if (!newValue) {
              unwatch();
              resolve();
            }
          });
          setTimeout(() => {
            unwatch();
            resolve();
          }, 15000);
        });

        const practitionerId =
          this.loggedInStaff && this.loggedInStaff.practitioner;
        if (!practitionerId) {
          this.accessChecked = true;
          return;
        }

        const resp = await fetch(
          "/site/general/getDepartmentalDirector/" + practitionerId,
        );
        if (!resp.ok) throw new Error("HTTP " + resp.status);
        const directors = await resp.json();
        this.isDirector = Array.isArray(directors)
          ? directors.some((d) => d.practitioner === practitionerId)
          : false;
      } catch (err) {
        console.error("checkAccess error:", err);
        this.isDirector = false;
      } finally {
        this.accessChecked = true;
      }
    },

    async loadStatusValueSet() {
      try {
        const items = await this.$fhirutils.expand(
          "http://ihris.org/fhir/ValueSet/request-status-valueset",
        );
        this.statusValueSetItems = items || [];
      } catch (err) {
        console.error("loadStatusValueSet error:", err);
      }
    },

    // Resolve one position's designation/facility directly by id, rather
    // than bulk-listing via /site/position/report — that endpoint clamps
    // `count` to 100 server-side, so preloading "all" positions silently
    // drops anything past the first 100 and any position outside that page
    // (e.g. a destination position picked from later results) never
    // resolves. Direct-by-id lookup scales with the visible list, not the
    // whole position catalog, and mirrors what the detail view does.
    async resolvePosition(ref) {
      if (!ref) return {};
      if (this.positionsMap[ref]) return this.positionsMap[ref];
      try {
        const id = ref.includes("/") ? ref.split("/")[1] : ref;
        const res = await fetch(`/fhir/Basic/${id}`);
        if (!res.ok) {
          console.error(
            `resolvePosition: GET /fhir/Basic/${id} (${ref}) → HTTP ${res.status}`,
          );
          return {};
        }
        const position = await res.json();
        const getExt = (part, type) =>
          position.extension?.find((e) => e.url.includes(part))?.[type];

        let designation = "";
        const designationRef = getExt("designation", "valueReference")
          ?.reference;
        if (designationRef) {
          try {
            const dId = designationRef.split("/")[1];
            const dRes = await fetch(`/fhir/Basic/${dId}`);
            const dData = await dRes.json();
            designation =
              dData.extension?.find((e) => e.url.includes("ihris-basic-name"))
                ?.valueString || "";
          } catch {
            // designation lookup best-effort
          }
        }

        let facility = "";
        const facilityRef = getExt("facility", "valueReference")?.reference;
        if (facilityRef) {
          try {
            const fId = facilityRef.split("/")[1];
            const fRes = await fetch(`/fhir/Location/${fId}`);
            const fData = await fRes.json();
            facility = fData.name || "";
          } catch {
            // facility lookup best-effort
          }
        }

        const result = {
          designation,
          facility,
          department: getExt("department", "valueCoding")?.display || "",
        };
        this.positionsMap[ref] = result;
        return result;
      } catch (err) {
        console.error("resolvePosition error:", err);
        return {};
      }
    },

    // Extension urls are derived from the *Extension definition's* id, not
    // the FSH slice name — e.g. the "current-position" slice is defined by
    // the "PositionReference" extension (id: position-reference), and
    // "destination-position" by "DestinationPosition" (id: destition-position,
    // a typo in the IG source). Try the canonical id(s) first and fall back
    // to the slice name in case that ever gets corrected upstream.
    getExt(resource, urlParts) {
      const candidates = Array.isArray(urlParts) ? urlParts : [urlParts];
      const exts = resource.extension || [];
      for (const part of candidates) {
        const found = exts.find((e) => e.url.includes(part));
        if (found) return found;
      }
      return null;
    },

    async loadRecommendations() {
      this.loading = true;
      this.loadError = null;
      try {
        this.positionsMap = {};

        // Restrict the list to recommendations whose current position sits
        // in the logged-in Departmental Director's own department — chains
        // through the "position" search param (HODRecommendedTransfer's
        // current-position reference) onto Position's own "department"
        // token search param.
        const deptCode = this.loggedInStaff?.department?.code;
        let url = `/fhir/Basic?_profile=${PROFILE}&_count=200`;
        if (deptCode) {
          url += `&position.department=${encodeURIComponent(deptCode)}`;
        }

        const res = await fetch(url);
        const bundle = await res.json();
        const resources = (bundle.entry || []).map((e) => e.resource);

        const practRefs = [
          ...new Set(
            resources
              .map(
                (r) =>
                  this.getExt(r, [
                    "ihris-practitioner-reference",
                    "practitioner",
                  ])?.valueReference?.reference,
              )
              .filter(Boolean),
          ),
        ];

        const nameMap = {};
        await Promise.all(
          practRefs.map(async (ref) => {
            try {
              const r = await fetch(`/fhir/${ref}?_elements=name`);
              const pract = await r.json();
              const name = pract.name?.[0];
              nameMap[ref] = name
                ? `${(name.given || []).join(" ")} ${name.family || ""}`.trim()
                : ref;
            } catch {
              nameMap[ref] = ref;
            }
          }),
        );

        // Resolve exactly the current/destination position refs this list
        // needs, directly by id (see resolvePosition for why not bulk-listed).
        const positionRefs = [
          ...new Set(
            resources.flatMap((r) => [
              this.getExt(r, ["position-reference", "current-position"])
                ?.valueReference?.reference,
              this.getExt(r, ["destination-position", "destition-position"])
                ?.valueReference?.reference,
            ]),
          ),
        ].filter(Boolean);

        await Promise.all(positionRefs.map((ref) => this.resolvePosition(ref)));

        this.recommendations = resources.map((r) => {
          const practRef = this.getExt(r, [
            "ihris-practitioner-reference",
            "practitioner",
          ])?.valueReference?.reference;
          const curRef = this.getExt(r, [
            "position-reference",
            "current-position",
          ])?.valueReference?.reference;
          const destRef = this.getExt(r, [
            "destination-position",
            "destition-position",
          ])?.valueReference?.reference;
          const cur = this.positionsMap[curRef] || {};
          const dest = this.positionsMap[destRef] || {};
          const statusCoding = this.getExt(r, ["request-status", "status"])
            ?.valueCoding;
          const eventDate =
            this.getExt(r, "event-date")?.valueDate || r.meta?.lastUpdated;

          return {
            id: r.id,
            staffName: nameMap[practRef] || "Unknown",
            currentPosition: cur.designation || "—",
            currentFacility: cur.facility || "—",
            destinationPosition: dest.designation || "—",
            destinationFacility: dest.facility || "—",
            plannedTransferDate: this.getExt(r, "planned-transfer-date")
              ?.valueDate,
            transferReason: this.getExt(r, ["reason", "transfer-reason"])
              ?.valueString,
            status: statusCoding?.code || null,
            statusDisplay: statusCoding?.display || "Pending",
            eventDate,
          };
        });

        this.recommendations.sort(
          (a, b) => new Date(b.eventDate || 0) - new Date(a.eventDate || 0),
        );

        this.applyFilters();
      } catch (err) {
        console.error("loadRecommendations error:", err);
        this.loadError =
          "Some records could not be loaded. Showing partial results.";
      } finally {
        this.loading = false;
      }
    },

    applyFilters() {
      const name = (this.filter.name || "").toLowerCase().trim();
      const status = this.filter.status;

      this.filteredRecommendations = this.recommendations.filter((row) => {
        if (name && !row.staffName.toLowerCase().includes(name)) return false;
        if (status && row.status !== status) return false;
        return true;
      });
    },

    onFilterChange() {
      clearTimeout(this.filterDebounce);
      this.filterDebounce = setTimeout(() => this.applyFilters(), 250);
    },

    resetFilters() {
      this.filter = { name: "", status: null };
      this.applyFilters();
    },

    newRecommendation() {
      this.$router.push({
        path: "/custom/hod-transfer-recommendation",
        query: { path: "/lesotho/components/transfers" },
      });
    },

    viewRecommendation(item) {
      this.$router.push({
        path: "/custom/hod-transfer-recommendation-view",
        query: {
          path: "/lesotho/components/transfers",
          id: item.id,
          returnLabel: "Back to Transfer Recommendations",
        },
      });
    },

    applyTransfer(item) {
      this.$router.push({
        path: "/custom/hod-apply-transfer",
        query: {
          path: "/lesotho/components/transfers",
          request: item.id,
        },
      });
    },

    statusKey(status) {
      if (!status) return "warn";
      if (status === "approved") return "done";
      if (status.includes("rejected")) return "error";
      if (status === "cancelled") return "none";
      if (status.includes("review")) return "active";
      return "warn";
    },

    formatDate(dateString) {
      if (!dateString) return "—";
      const date = new Date(dateString);
      if (isNaN(date.getTime())) return "—";
      const day = String(date.getDate()).padStart(2, "0");
      const month = String(date.getMonth() + 1).padStart(2, "0");
      return `${day}/${month}/${date.getFullYear()}`;
    },
  },
};
</script>

